var e={id:`p5-wave-interference`,title:`Wave Interference`,category:`wave`,description:`Four orbiting wave sources create interference patterns rendered via surface normal colour mapping.`,version:`1.1.0`,canvas:{width:1080,height:1080,context:`p5`},compute:{cost:`per-pixel`,interactionScale:.5,idleDelay:200},parameters:[{group:`Wave`,params:[{key:`amplitude`,type:`slider`,label:`Amplitude`,min:1,max:12,step:.5,default:4},{key:`frequency`,type:`slider`,label:`Frequency`,min:.05,max:.5,step:.01,default:.251},{key:`speed`,type:`slider`,label:`Speed`,min:.001,max:.1,step:.001,default:.02}]},{group:`Sources`,params:[{key:`s1Loops`,type:`slider`,label:`Source 1 Loops`,min:1,max:30,step:1,default:10},{key:`s2Loops`,type:`slider`,label:`Source 2 Loops`,min:1,max:30,step:1,default:7},{key:`s3Loops`,type:`slider`,label:`Source 3 Loops`,min:1,max:30,step:1,default:18},{key:`s4Loops`,type:`slider`,label:`Source 4 Loops`,min:1,max:30,step:1,default:3}]},{group:`Render`,params:[{key:`resolution`,type:`slider`,label:`Resolution`,min:1,max:6,step:1,default:2}]}],presets:[{name:`Classic`,values:{amplitude:4,frequency:.251,speed:.02,s1Loops:10,s2Loops:7,s3Loops:18,s4Loops:3,resolution:2}},{name:`High Freq`,values:{amplitude:3,frequency:.4,speed:.03,s1Loops:8,s2Loops:5,s3Loops:13,s4Loops:2,resolution:2}},{name:`Low Detail`,values:{amplitude:6,frequency:.15,speed:.015,s1Loops:10,s2Loops:7,s3Loops:18,s4Loops:3,resolution:4}}],animation:{type:`loop`,loopFrames:3600,defaultFps:60,animatableParams:[`amplitude`,`speed`,`frequency`],sequencer:!0},export:{png:!0,gif:!0,webm:!1},infoSections:[{heading:`DESCRIPTION`,body:`Wave Interference renders interference patterns from four orbiting wave sources on a 1080x1080 pixel canvas. Each pixel's colour is derived from the angular differences between the surface normals of two source pairs and a rotating reference vector. The generator is fully deterministic — every frame depends only on the frame number and current parameter values, with no random elements.`},{heading:`WAVE MODEL`,body:`Each source emits a scalar wave described by: h(px, py, src, t) = amplitude x (sin(frequency x distance - speed x t) + 1) / 2, where distance is the Euclidean distance from the pixel to the source. There is no distance decay — amplitude is uniform at all ranges. The wave heights of a source pair are summed at each pixel to produce a local surface height used for normal estimation.`},{heading:`SOURCE ORBITS`,body:`Four sources orbit the canvas perimeter continuously. Sources 1 and 2 form Pair A; sources 3 and 4 form Pair B. Sources 1 and 3 travel clockwise; sources 2 and 4 travel counter-clockwise. Start offsets are 0, half-perimeter, quarter-perimeter, and three-quarter-perimeter respectively. Each source completes its loop count per animation cycle. All positions are deterministic and frame-based.`},{heading:`SURFACE NORMALS`,body:`For each effective pixel, two surface normals are computed — one for Pair A and one for Pair B — using a 4-point finite difference of the summed wave heights at offsets of 1 pixel in each cardinal direction. The resulting gradient vector is normalised to a unit sphere. This gives a compact representation of the local surface tilt at the interference pattern's surface.`},{heading:`COLOUR MAPPING`,body:`Six angular differences are computed between the pair normals and a rotating reference vector: three from Pair A (XY, XZ, ZY planes) and three from Pair B. Each is wrapped to [-pi, pi]. The XY differences sum to the red channel, the XZ differences to green, and the ZY differences to blue. Each channel is linearly mapped from [-2pi, 2pi] to [0, 255]. A hue shift is then applied using the total summed wave height across all four sources, rotating the colour by up to 360 degrees.`},{heading:`REFERENCE VECTOR`,body:`The reference vector traces a triangle with vertices at approximately (540, 54), (1026, 1026), and (54, 1026) on the canvas, completing 10 circuits per animation cycle. The triangle position is converted to spherical coordinates — theta from the x-position and phi from the y-position — and mapped to a unit sphere. This rotating reference continuously shifts the colour output throughout the cycle.`},{heading:`PARAMETERS`,body:`Amplitude (1-12): wave height scale; higher values increase colour saturation and contrast. Frequency (0.05-0.5): spatial frequency of waves; higher values produce finer interference fringes. Speed (0.001-0.1): temporal phase rate; controls how fast the wave pattern evolves. Source 1-4 Loops (1-30): orbit count per cycle for each source; different values produce complex asymmetric patterns. Resolution (1-6): pixel block size for rendering; 1 is full quality at ~2-5 fps, 6 gives blocks at ~60 fps. The animation cycle is fixed at 3600 frames.`},{heading:`PERFORMANCE`,body:`At full resolution (1) the generator computes approximately 20 transcendental operations per pixel across 1.16 million pixels — expect 2-5 fps on the main thread. At the default resolution of 2 (291k effective pixels), expect 5-15 fps. Resolution 4 gives 20-40 fps; resolution 6 meets the 60 fps target. During parameter interaction, canvas resolution is automatically halved to maintain responsiveness, then restored after 200ms of inactivity. Use resolution 4-6 for real-time preview and resolution 1-2 for final output.`}],_triangle:[{x:540,y:54},{x:1026,y:1026},{x:54,y:1026}],_perimeterToXY(e,t,n){let r=2*(t+n);return e=(e%r+r)%r,e<t?{x:e,y:0}:e<t+n?{x:t,y:e-t}:e<2*t+n?{x:2*t+n-e,y:n}:{x:0,y:r-e}},_getSourcePos(e,t,n,r,i,a,o){let s=2*(a+o),c=r%i/i,l=t?1:-1,u=n+c*e*s*l;return this._perimeterToXY(u,a,o)},_getRefVector(e,t,n,r){let i=e%t/t*10%1*3,a=Math.floor(i)%3,o=i-a,s=this._triangle[a],c=this._triangle[(a+1)%3],l=s.x+(c.x-s.x)*o,u=s.y+(c.y-s.y)*o,d=l/n*Math.PI*2,f=u/r*Math.PI;return{x:Math.sin(f)*Math.cos(d),y:Math.sin(f)*Math.sin(d),z:Math.cos(f)}},_waveHeight(e,t,n,r,i,a,o){let s=e-n.x,c=t-n.y,l=Math.sqrt(s*s+c*c);return i*(Math.sin(a*l-o*r)+1)/2},_sumHeight(e,t,n,r,i,a,o){return n.reduce((n,s)=>n+this._waveHeight(e,t,s,r,i,a,o),0)},_calcNormal(e,t,n,r,i,a,o){let s=this._sumHeight(e-1,t,n,r,i,a,o),c=this._sumHeight(e+1,t,n,r,i,a,o),l=this._sumHeight(e,t-1,n,r,i,a,o),u=this._sumHeight(e,t+1,n,r,i,a,o),d=-(c-s)/2,f=-(u-l)/2,p=Math.sqrt(d*d+f*f+1);return{x:d/p,y:f/p,z:1/p}},_wrapAngle(e){for(;e>Math.PI;)e-=2*Math.PI;for(;e<-Math.PI;)e+=2*Math.PI;return e},_mapToColor(e,t,n){return Math.round(Math.max(0,Math.min(255,(e-t)/(n-t)*255)))},_deltaToRGB(e,t,n,r,i){let a=this._wrapAngle(Math.atan2(e.y,e.x)-n),o=this._wrapAngle(Math.atan2(e.z,e.x)-r),s=this._wrapAngle(Math.atan2(e.y,e.z)-i),c=this._wrapAngle(Math.atan2(t.y,t.x)-n),l=this._wrapAngle(Math.atan2(t.z,t.x)-r),u=this._wrapAngle(Math.atan2(t.y,t.z)-i),d=2*Math.PI;return{r:this._mapToColor(a+c,-d,d),g:this._mapToColor(o+l,-d,d),b:this._mapToColor(s+u,-d,d)}},_hueShift(e,t){let n=e.r/255,r=e.g/255,i=e.b/255,a=Math.max(n,r,i),o=Math.min(n,r,i),s,c,l=(a+o)/2;if(a===o)s=c=0;else{let e=a-o;switch(c=l>.5?e/(2-a-o):e/(a+o),a){case n:s=((r-i)/e+(r<i?6:0))/6;break;case r:s=((i-n)/e+2)/6;break;default:s=((n-r)/e+4)/6;break}}s=((s*360+t)%360+360)%360/360;let u=(e,t,n)=>(n<0&&(n+=1),n>1&&--n,n<1/6?e+(t-e)*6*n:n<1/2?t:n<2/3?e+(t-e)*(2/3-n)*6:e),d,f,p;if(c===0)d=f=p=l;else{let e=l<.5?l*(1+c):l+c-l*c,t=2*l-e;d=u(t,e,s+1/3),f=u(t,e,s),p=u(t,e,s-1/3)}return{r:Math.round(d*255),g:Math.round(f*255),b:Math.round(p*255)}},p5Setup(e,t){e.pixelDensity(1),e.noLoop()},p5Draw(e,t,n){let{amplitude:r,frequency:i,speed:a,s1Loops:o,s2Loops:s,s3Loops:c,s4Loops:l,resolution:u}=t,d=this.animation.loopFrames,f=e.width,p=e.height,m=2*(f+p),h=n,g=[this._getSourcePos(o,!0,0,h,d,f,p),this._getSourcePos(s,!0,m/2,h,d,f,p),this._getSourcePos(c,!1,m/4,h,d,f,p),this._getSourcePos(l,!1,3*m/4,h,d,f,p)],_=[g[0],g[1]],v=[g[2],g[3]],y=g,b=this._getRefVector(h,d,f,p),x=Math.atan2(b.y,b.x),S=Math.atan2(b.z,b.x),C=Math.atan2(b.y,b.z);e.loadPixels();let w=u;for(let t=0;t<p;t+=w)for(let n=0;n<f;n+=w){let o=this._calcNormal(n,t,_,h,r,i,a),s=this._calcNormal(n,t,v,h,r,i,a),c=this._deltaToRGB(o,s,x,S,C),l=this._sumHeight(n,t,y,h,r,i,a);c=this._hueShift(c,l/16*360);for(let r=0;r<w&&t+r<p;r++)for(let i=0;i<w&&n+i<f;i++){let a=4*((t+r)*f+(n+i));e.pixels[a]=c.r,e.pixels[a+1]=c.g,e.pixels[a+2]=c.b,e.pixels[a+3]=255}}e.updatePixels()}};export{e as SCRIPT_CONFIG};